export function Toolbar() {
  return createElement(
    'nav',
    { className: 'toolbar' },
    createElement('span', { className: 'doc-title' }, 'Untitled'),
    createElement('button', { type: 'button', className: 'ghost' }, 'Cancel'),
  );
}

import { createElement } from '../../vendor/react.js';
import { classNames } from '../../lib/classNames.js';

export function Pressable({
  variant = 'secondary',
  disabled = false,
  children = '',
} = {}) {
  const kind = variant === 'primary' ? 'primary' : 'secondary';
  return createElement(
    'button',
    {
      type: 'button',
      className: classNames('btn', `btn-${kind}`),
      disabled: Boolean(disabled),
    },
    children,
  );
}

import { createElement } from '../../vendor/react.js';
import { Pressable } from '../ui/Pressable.js';
import { TextField } from '../ui/TextField.js';

export function LoginForm() {
  return createElement(
    'form',
    { className: 'login' },
    createElement(TextField, { id: 'email', name: 'email', label: 'Email', type: 'email' }),
    createElement(Pressable, { variant: 'primary', children: 'Sign in' }),
  );
}

export function createElement(type, props, ...children) {
  return {
    type,
    props: props || {},
    children: children.flat().filter((child) => child !== null && child !== undefined),
  };
}

export default { createElement };

